    ('f7dc20d6-aa71-46fa-8e27-19779a1187fb'::uuid, 'wikidata_qid', 'Q1142826', NULL, 'external-id:da7877b7a2ade7294d6e8cef2d6d6057a9ad6ec86c9e685f2057df8f6bc6293e', 'L5/wikidata_qid', 'authoritative', '[{"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "L5 reading (r1, r1-b16 (2026-09-26T13:15:28+00:00)): wikidata_qid REMOVE - The name designates the Valley of the Caves (Valle de las Cuevas, ''Cave Valley''), the cave valley near Ignacio Zaragoza south-west of Nuevo Casas Grandes with Cueva de la Olla and Cueva de la Golondrina; the Megalithic Portal entry the record follows gives ''Cave Valley, Olla Cave'' as its alternative names but put its dot on Cuarenta Casas. Q1142826 is Cuarenta Casas, a different cliff-dwelling site in Huapoca Canyon, not this valley. No Wikidata item is the Chihuahua valley itself (Q1143225 Cueva de la Olla is one cave in it, about 69 km from the stored point), so the site keeps no item.", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q1142826.json: \"Archaeological site in the northern Mexican state of Chihuahua\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://en.wikipedia.org/wiki/Cuarenta_Casas: \"The site consists of a series of cliff dwellings built in natural caves in the cliffs of Huapoca Canyon.\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.megalithic.co.uk/article.php?sid=33489: \"Cave Valley, Olla Cave\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://en.wikipedia.org/wiki/Cueva_de_la_Olla_(archaeological_site): \"is an archaeological site located in the Valle de las Cuevas in northwestern\"", "url": null}]'::jsonb),
    ('f7dc20d6-aa71-46fa-8e27-19779a1187fb'::uuid, 'enwiki_title', 'Cuarenta Casas', NULL, 'external-id:4feea4cc1ab52b0ed00e003af881266f5e8030fbde814a74f259fc24354cb6fa', 'L5/enwiki_title', 'authoritative', '[{"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "L5 reading (r1, r1-b16 (2026-09-26T13:15:28+00:00)): enwiki_title REMOVE - The article Cuarenta Casas is about the Huapoca Canyon cliff dwellings, not the Valley of the Caves near Nuevo Casas Grandes; no English article is about the valley itself.", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://en.wikipedia.org/wiki/Cuarenta_Casas: \"The site consists of a series of cliff dwellings built in natural caves in the cliffs of Huapoca Canyon.\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.mexconnect.com/articles/1451-the-valley-of-the-caves/: \"Today, the Valley of the Caves can be reached from nearby Nuevo Casas Grandes in northern Chihuahua.\"", "url": null}]'::jsonb),
    ('f8c28568-017a-4b61-903c-bed2ba67bce0'::uuid, 'wikidata_qid', 'Q5192640', NULL, 'external-id:a48bf0f7665cb807df8870a19c69cee79e3629f2dec5c969d2948f910ebb29f1', 'L5/wikidata_qid', 'authoritative', '[{"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "L5 reading (r1, r1-b16 (2026-09-26T13:17:14+00:00)): wikidata_qid REMOVE - ''Madera Caves'' is the group of Paquime-culture cave sites of the Madera municipality (the Megalithic Portal entry the record follows describes several zones in the area; the record''s own text lists Huapoca, Cueva Grande, La Rancheria, Cueva del Puente and Cuarenta Casas). Q5192640 is Cueva de la Momia, one cave of that region about 62 km south of the stored point - a member, not the group. No Wikidata item is exactly the Madera caves as a group (wbsearchentities finds none), so the site keeps no item.", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q5192640.json: \"Cueva de la Momia\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://en.wikipedia.org/wiki/Cueva_de_la_Momia: \"Cueva de la Momia is an archaeological site located in the region of Ciudad Madera\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.megalithic.co.uk/article.php?sid=33502: \"There are several Paquimé culture archaeological zones in the area of Madera municipality.\"", "url": null}]'::jsonb),
    ('f8c28568-017a-4b61-903c-bed2ba67bce0'::uuid, 'enwiki_title', 'Cueva de la Momia', NULL, 'external-id:506cbdb4cd0d2a9c7c9ab59d36d1fd800ad4db2f60251383eb11de52cb60ff4b', 'L5/enwiki_title', 'authoritative', '[{"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "L5 reading (r1, r1-b16 (2026-09-26T13:17:14+00:00)): enwiki_title REMOVE - The article Cueva de la Momia is about a single cave in the Sirupa Canyon region, not about the Madera caves as a group; no English article is about the group itself.", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://en.wikipedia.org/wiki/Cueva_de_la_Momia: \"in the Sirupa Canyon region, in the northwest of the Mexican state of\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://en.wikipedia.org/wiki/Cuarenta_Casas: \"There are five Paquimé Culture archaeological sites in this area, accessible from the Madera municipality.\"", "url": null}]'::jsonb),
    ('f984f67d-95a3-4a2d-9e69-977cfb7a2e4f'::uuid, 'wikidata_qid', 'Q4697343', 'Q135269682', 'external-id:778950df35d54242b5999f3101e8fda8cabd65e0ed3260f577fb02c6fd8e8a7f', 'L5/wikidata_qid', 'authoritative', '[{"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "L5 reading (r1, r1-b16 (2026-09-26T13:19:11+00:00)): wikidata_qid REPLACE - Q4697343 is the village of Ain Harcha (a human settlement), the container the temple lies near - not the temple. Q135269682 ''Ain Harcha Roman Temple'' (alias ''Ain Hircha, Ain Hirsha'') is exactly this Roman temple; its P625 (33.45352, 35.79044) is about 30 m from the stored point.", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q135269682.json: \"Ain Harcha Roman Temple\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q135269682.json: \"Roman temple in Lebanon dedicated in 116 CE\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q135269682.json: \"Ain Hircha, Ain Hirsha\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q4697343.json: \"human settlement in Lebanon\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "machine check: Q135269682 (''Ain Harcha Roman Temple''): P625 30 m from the stored point", "url": null}]'::jsonb),
    ('f984f67d-95a3-4a2d-9e69-977cfb7a2e4f'::uuid, 'enwiki_title', 'Ain Harcha', NULL, 'external-id:2b48e2df0bcb40a32ffbeae3bb6d6ad5cd1f411cbff26b0ee8121a7cce830cb0', 'L5/enwiki_title', 'authoritative', '[{"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "L5 reading (r1, r1-b16 (2026-09-26T13:19:11+00:00)): enwiki_title REMOVE - The article Ain Harcha is about the village in the Rashaya District (its item is Q4697343); the temple is only a section of it. No English article is about the temple itself, and Q135269682 has no enwiki sitelink.", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://en.wikipedia.org/wiki/Ain_Harcha: \"is a village situated in the Rashaya District\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://en.wikipedia.org/wiki/Ain_Harcha: \"The village is home to a Roman temple.\"", "url": null}]'::jsonb),
    ('fcd0a337-27f9-4223-82e9-d89a98795bd3'::uuid, 'wikidata_qid', 'Q608095', 'Q134728223', 'external-id:24f71aa8f68682f5060a24acdd732a5dae1c29c6f75e3063a8d407e35936fdae', 'L5/wikidata_qid', 'authoritative', '[{"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "L5 reading (r1, r1-b16 (2026-09-26T13:22:16+00:00)): wikidata_qid REPLACE - The record is the rock-cut ''Tombs of the Kings'' in the cliff at Kaunos opposite Dalyan, not the whole city: Q608095 is the ancient city Kaunos (the container, already the link of the curated row ''Kaunos''). Q134728223 is labelled ''Kaunos Kaya Mezarlari'' (Turkish for ''Kaunos Rock Tombs''), described as a rock-cut tomb in Koycegiz District, with the Commons category ''Kaunos rock graves''; its P625 (36.83358, 28.63419) is about 143 m from the stored point - exactly this group of royal rock tombs.", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q134728223.json: \"Kaunos Kaya Mezarları\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q134728223.json: \"mausoleum, rock-cut tomb in Köyceğiz District\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q134728223.json: \"Kaunos rock graves\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://www.wikidata.org/wiki/Special:EntityData/Q608095.json: \"ancient city in Turkey\"", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "machine check: Q134728223 (None): P625 143 m from the stored point", "url": null}]'::jsonb),
    ('fcd0a337-27f9-4223-82e9-d89a98795bd3'::uuid, 'enwiki_title', 'Kaunos', NULL, 'external-id:10ed457479ab2b7d6bb0a7793fefb0886771d9c7d47d52348096ba54f87a7367', 'L5/enwiki_title', 'authoritative', '[{"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "L5 reading (r1, r1-b16 (2026-09-26T13:22:16+00:00)): enwiki_title REMOVE - The article Kaunos is about the ancient city as a whole (its item is Q608095), the container of the tombs; no English article is about the rock tombs themselves, and Q134728223 has no enwiki sitelink.", "url": null}, {"source": "L5 link pass 2026-09-26 (Opus reading, quotes machine-checked)", "quote": "https://en.wikipedia.org/wiki/Kaunos: \"was a city of ancient\"", "url": null}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    n        INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 198;
    r        RECORD;
BEGIN
    -- guard 1: every site is a curated site that still exists
    SELECT count(*) INTO bad
      FROM (SELECT site_id FROM _url_plan UNION SELECT site_id FROM _ext_plan) p
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN RAISE EXCEPTION 'source-url split: % site(s) are not curated sites', bad;
    END IF;
    -- guard 2: every source_url still holds the planned old value
    SELECT count(*) INTO bad FROM _url_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE u.source_url IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % source_url value(s) no longer hold the planned old value', bad;
    END IF;
    -- guard 3: an external-id row with an old value is the one row of its kind and holds it
    SELECT count(*) INTO bad FROM _ext_plan p
     WHERE p.old_value IS NOT NULL
       AND ((SELECT count(*) FROM site_external_ids e
              WHERE e.site_id = p.site_id AND e.kind = p.kind) <> 1
         OR NOT EXISTS (SELECT 1 FROM site_external_ids e WHERE e.site_id = p.site_id
                           AND e.kind = p.kind AND e.value = p.old_value));
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % external-id row(s) no longer hold the planned old value', bad;
    END IF;
    -- guard 4: a row planned as new is new - the site holds no row of its kind
    SELECT count(*) INTO bad FROM _ext_plan p
     WHERE p.old_value IS NULL
       AND EXISTS (SELECT 1 FROM site_external_ids e WHERE e.site_id = p.site_id AND e.kind = p.kind);
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % site(s) already hold a row of a kind planned as new', bad;
    END IF;
    -- guard 5: no other curated site carries a planned item
    SELECT count(*) INTO bad FROM _ext_plan p
      JOIN site_external_ids e ON e.kind = p.kind AND e.value = p.new_value AND e.site_id <> p.site_id
      JOIN unified_sites u ON u.id = e.site_id AND u.source_id = 'ancient_nerds'
     WHERE p.kind = 'wikidata_qid';
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % planned item(s) are carried by another curated site', bad;
    END IF;
    -- guard 6: no item is planned for two sites (guard 5 reads the state before the
    -- write, so two planned sites given one new item would both pass it)
    SELECT count(*) INTO bad FROM (SELECT new_value FROM _ext_plan
     WHERE kind = 'wikidata_qid' AND new_value IS NOT NULL
     GROUP BY new_value HAVING count(*) > 1) d;
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % item(s) are planned for more than one site', bad;
    END IF;
    -- the source_url writes: the journal primitive, one call and one journal row each
    FOR r IN SELECT * FROM _url_plan ORDER BY site_id LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', 'source_url', 'id', r.site_id::text, r.old_value, r.new_value,
            r.test_id, '2026-09-26_l5-links-001', r.change_key, r.confidence, r.evidence, r.site_id);
    END LOOP;
    -- the external-id writes: exactly one row each, and its journal row
    FOR r IN SELECT * FROM _ext_plan ORDER BY site_id, kind LOOP
        IF r.old_value IS NULL THEN
            INSERT INTO site_external_ids (site_id, kind, value) VALUES (r.site_id, r.kind, r.new_value);
        ELSIF r.new_value IS NULL THEN
            DELETE FROM site_external_ids
             WHERE site_id = r.site_id AND kind = r.kind AND value = r.old_value;
        ELSE
            UPDATE site_external_ids SET value = r.new_value
             WHERE site_id = r.site_id AND kind = r.kind AND value = r.old_value;
        END IF;
        GET DIAGNOSTICS n = ROW_COUNT;
        IF n <> 1 THEN
            RAISE EXCEPTION 'source-url split: %/% matched % row(s), not 1',
                r.site_id, r.kind, n;
        END IF;
        INSERT INTO remediation_change_log (run_stamp, test_id, table_name, column_name,
            row_pk, old_value, new_value, change_key, confidence, evidence, site_id_ref)
        VALUES ('2026-09-26_l5-links-001', r.test_id, 'site_external_ids', 'value',
            r.site_id::text || '/' || r.kind, r.old_value, r.new_value, r.change_key,
            r.confidence, r.evidence, r.site_id);
        moved := moved + n;
    END LOOP;
    IF moved <> expected THEN
        RAISE EXCEPTION 'source-url split: % row(s) changed, % planned', moved, expected;
    END IF;
    -- invariant 1: every source_url holds its new value
    SELECT count(*) INTO bad FROM _url_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE u.source_url IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % source_url value(s) do not hold the new value', bad;
    END IF;
    -- invariant 2: an external-id row holds its new value and is the one row of its kind;
    -- a row the plan removes is gone
    SELECT count(*) INTO bad FROM _ext_plan p
     WHERE (p.new_value IS NOT NULL
            AND ((SELECT count(*) FROM site_external_ids e WHERE e.site_id = p.site_id
                   AND e.kind = p.kind AND e.value = p.new_value) <> 1
              OR (SELECT count(*) FROM site_external_ids e
                   WHERE e.site_id = p.site_id AND e.kind = p.kind) <> 1))
        OR (p.new_value IS NULL
            AND EXISTS (SELECT 1 FROM site_external_ids e WHERE e.site_id = p.site_id AND e.kind = p.kind));
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % external-id row(s) do not hold the new value', bad;
    END IF;
    -- invariant 3: the journal and the plan agree in both directions
    SELECT count(*) INTO bad FROM (
        SELECT change_key, 'unified_sites' AS table_name, 'source_url' AS column_name,
               site_id::text AS row_pk, old_value, new_value FROM _url_plan
        UNION ALL
        SELECT change_key, 'site_external_ids', 'value', site_id::text || '/' || kind,
               old_value, new_value FROM _ext_plan
    ) p LEFT JOIN remediation_change_log l
        ON l.run_stamp = '2026-09-26_l5-links-001' AND l.change_key = p.change_key
       AND l.table_name = p.table_name AND l.column_name = p.column_name
       AND l.row_pk = p.row_pk AND l.old_value IS NOT DISTINCT FROM p.old_value
       AND l.new_value IS NOT DISTINCT FROM p.new_value
     WHERE l.id IS NULL;
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % row(s) have no matching journal row', bad;
    END IF;
    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-09-26_l5-links-001'
       AND NOT EXISTS (SELECT 1 FROM _url_plan p WHERE p.change_key = l.change_key)
       AND NOT EXISTS (SELECT 1 FROM _ext_plan p WHERE p.change_key = l.change_key);
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: this stamp journalled % row(s) outside the plan',
            bad;
    END IF;
    -- invariant 4: the fixed point - no planned site is left without an external-id row
    -- while its source_url is an English Wikipedia article (the daily refresh would
    -- resolve it and write the removed link back)
    SELECT count(*) INTO bad
      FROM (SELECT site_id FROM _url_plan UNION SELECT site_id FROM _ext_plan) p
      JOIN unified_sites u ON u.id = p.site_id
     WHERE u.source_url LIKE 'https://en.wikipedia.org/wiki/%'
       AND NOT EXISTS (SELECT 1 FROM site_external_ids e WHERE e.site_id = p.site_id);
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % site(s) left without a link on an English Wikipedia source_url', bad;
    END IF;
    -- invariant 5: every item written is carried by exactly one curated site
    SELECT count(*) INTO bad FROM _ext_plan p
     WHERE p.kind = 'wikidata_qid' AND p.new_value IS NOT NULL
       AND (SELECT count(*) FROM site_external_ids e
              JOIN unified_sites u ON u.id = e.site_id AND u.source_id = 'ancient_nerds'
             WHERE e.kind = 'wikidata_qid' AND e.value = p.new_value) <> 1;
    IF bad > 0 THEN
        RAISE EXCEPTION 'source-url split: % written item(s) are not carried by exactly one curated site', bad;
    END IF;
    RAISE NOTICE 'source-url split: % row(s) changed and journalled', moved;
END $$;

COMMIT;

SELECT 'journal rows for this stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-09-26_l5-links-001';
